contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public {
        bool before = c.distributionFinished(); if (__ESBMC_reverted()) return;
        bool ok;
        bool r = c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = r; }
        bool finishedNow = c.distributionFinished(); if (__ESBMC_reverted()) return;
        assert(before ? (finishedNow == before) : (ok && finishedNow));
    }
}

