pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 dummy) internal {
        bool before;
        try c.distributionFinished() returns (bool __r) { before = __r; } catch { return; }
        bool ok;
        try c.finishDistribution() returns (bool r) { ok = r; } catch { ok = false; }
        bool finishedNow;
        try c.distributionFinished() returns (bool __r) { finishedNow = __r; } catch { return; }
        assertTrue(before ? (finishedNow == before) : (ok && finishedNow));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
